import React, { useState } from 'react';
import { StyleSheet, View, ScrollView } from 'react-native';
import Header from '../components/Header';
import WeeklyCalendar from '../components/WeeklyCalendar';
import WeeklyGrid from '../components/WeeklyGrid';
import EmployeeSuggestion from '../components/EmployeeSuggestion';

const WeeklyScheduleScreen = () => {
  const [selectedDate, setSelectedDate] = useState(28);
  const [currentWeek, setCurrentWeek] = useState('28/04 - 01/05');

  return (
    <View style={styles.container}>
      <Header currentWeek={currentWeek} onWeekChange={setCurrentWeek} />
      <ScrollView style={styles.content} showsVerticalScrollIndicator={false}>
        <WeeklyCalendar 
          selectedDate={selectedDate}
          onDateSelect={setSelectedDate}
        />
        <WeeklyGrid selectedDate={selectedDate} />
        <EmployeeSuggestion />
      </ScrollView>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#ffffff',
  },
  content: {
    flex: 1,
  },
});

export default WeeklyScheduleScreen;
